// PreToolUse (edit_file|write_file): block hand edits of generated files.
import { readFileSync } from 'node:fs';

const raw = readFileSync(0, 'utf8');
const input = raw.trim() ? JSON.parse(raw) : {};
const f = (input.toolCall?.args?.Path || '').replaceAll('\\', '/');

const rules = [
  [/\/styles\/(brand|theme)\.css$/, 'Generated from tokens/: edit the JSON in tokens/ and run `pnpm tokens`.'],
  [/\/messages\/en\.d\.json\.ts$/, 'Generated by pnpm dev/build from messages/en.json: edit en.json instead.'],
];

for (const [re, why] of rules) {
  if (re.test(f)) {
    process.stdout.write(JSON.stringify({ decision: 'deny', reason: why }));
    process.exit(0);
  }
}

process.stdout.write(JSON.stringify({ decision: 'allow' }));
